from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.adj[u].append([v, cap, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def _bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v, cap, rev in self.adj[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] >= 0

    def _dfs(self, u, t, f):
        if u == t:
            return f
        while self.it[u] < len(self.adj[u]):
            e = self.adj[u][self.it[u]]
            v, cap, rev = e
            if cap > 0 and self.level[v] == self.level[u] + 1:
                pushed = self._dfs(v, t, min(f, cap))
                if pushed:
                    e[1] -= pushed
                    self.adj[v][rev][1] += pushed
                    return pushed
            self.it[u] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10 ** 18
        while self._bfs(s, t):
            self.it = [0] * self.n
            while True:
                pushed = self._dfs(s, t, INF)
                if not pushed:
                    break
                flow += pushed
        return flow

if __name__ == "__main__":
    # 经典图: s=0, t=3; 边 0->1(3) 0->2(3) 1->2(2) 1->3(3) 2->3(3); 最大流=6
    g = Dinic(4)
    g.add_edge(0, 1, 3); g.add_edge(0, 2, 3)
    g.add_edge(1, 2, 2); g.add_edge(1, 3, 3); g.add_edge(2, 3, 3)
    assert g.max_flow(0, 3) == 6
    # EK 交叉验证
    import random
    def ek_max_flow(n, edges, s, t):
        cap = {}
        def key(u, v): return (u, v)
        for u, v, c in edges:
            cap[key(u, v)] = cap.get(key(u, v), 0) + c
        flow = 0
        while True:
            parent = [-1] * n
            parent[s] = s
            q = deque([s])
            while q and parent[t] == -1:
                u = q.popleft()
                for v in range(n):
                    if parent[v] == -1 and cap.get(key(u, v), 0) > 0:
                        parent[v] = u
                        q.append(v)
            if parent[t] == -1:
                break
            # 找瓶颈
            f = 10 ** 18
            v = t
            while v != s:
                u = parent[v]
                f = min(f, cap[key(u, v)])
                v = u
            v = t
            while v != s:
                u = parent[v]
                cap[key(u, v)] -= f
                cap[key(v, u)] = cap.get(key(v, u), 0) + f
                v = u
            flow += f
        return flow

    random.seed(3)
    for _ in range(150):
        n = random.randint(2, 8)
        edges = []
        for u in range(n):
            for v in range(n):
                if u != v and random.random() < 0.25:
                    edges.append((u, v, random.randint(1, 8)))
        s = 0; t = n - 1
        g = Dinic(n)
        for u, v, c in edges:
            g.add_edge(u, v, c)
        got = g.max_flow(s, t)
        exp = ek_max_flow(n, edges, s, t)
        assert got == exp, (n, edges, got, exp)
    print("Dinic OK")
